from typing import Iterable, List

from hourglass.parsing import format_span
from hourglass.models import Span
from hourglass.merging import merge_spans


def _check_inside(spans, hours: Span) -> None:
    for s in spans:
        if s.start < hours.start or s.end > hours.end:
            raise ValueError(
                f"{format_span(s)} is outside opening hours"
            )


def _stretch(start: int, end: int) -> str:
    span = Span(start, end)
    return f"gap {format_span(span)} ({span.minutes} min)"


def _walk(merged, hours: Span):
    pos = hours.start
    for s in merged:
        if s.start > pos:
            yield _stretch(pos, s.start)
        pos = s.end
    if pos < hours.end:
        yield _stretch(pos, hours.end)


def find_gaps(
    worked: Iterable[Span], hours: Span
) -> List[str]:
    """Labels such as 'gap 12:00-13:00 (60 min)'."""
    spans = list(worked)
    _check_inside(spans, hours)
    return list(_walk(merge_spans(spans), hours))

